138: func (l *raftLog) append(ents ...pb.Entry) uint64 {
139: 	if len(ents) == 0 {
140: 		return l.lastIndex()
141: 	}
142: 	if after := ents[0].Index - 1; after < l.committed {
143: 		l.logger.Panicf("after(%d) is out of range [committed(%d)]", after, l.committed)
144: 	}
145: 	l.unstable.truncateAndAppend(ents)
146: 	return l.lastIndex()
147: }
