174: // findConflictByTerm returns a best guess on where this log ends matching
175: // another log, given that the only information known about the other log is the
176: // (index, term) of its single entry.
177: //
178: // Specifically, the first returned value is the max guessIndex <= index, such
179: // that term(guessIndex) <= term or term(guessIndex) is not known (because this
180: // index is compacted or not yet stored).
181: //
182: // The second returned value is the term(guessIndex), or 0 if it is unknown.
183: //
184: // This function is used by a follower and leader to resolve log conflicts after
185: // an unsuccessful append to a follower, and ultimately restore the steady flow
186: // of appends.
187: func (l *raftLog) findConflictByTerm(index uint64, term uint64) (uint64, uint64) {
188: 	for ; index > 0; index-- {
189: 		// If there is an error (likely ErrCompacted or ErrUnavailable), we don't
190: 		// know whether it's a match or not, so assume a possible match and return
191: 		// the index, with 0 term indicating an unknown term.
192: 		if ourTerm, err := l.term(index); err != nil {
193: 			return index, 0
194: 		} else if ourTerm <= term {
195: 			return index, ourTerm
196: 		}
197: 	}
198: 	return 0, 0
199: }
