207: // hasNextUnstableEnts returns if there are any entries that are available to be
208: // written to the local stable log and are not already in-progress.
209: func (l *raftLog) hasNextUnstableEnts() bool {
210: 	return len(l.nextUnstableEnts()) > 0
211: }
