213: // hasNextOrInProgressUnstableEnts returns if there are any entries that are
214: // available to be written to the local stable log or in the process of being
215: // written to the local stable log.
216: func (l *raftLog) hasNextOrInProgressUnstableEnts() bool {
217: 	return len(l.unstable.entries) > 0
218: }
