268: // maxAppliableIndex returns the maximum committed index that can be applied.
269: // If allowUnstable is true, committed entries from the unstable log can be
270: // applied; otherwise, only entries known to reside locally on stable storage
271: // can be applied.
272: func (l *raftLog) maxAppliableIndex(allowUnstable bool) uint64 {
273: 	hi := l.committed
274: 	if !allowUnstable {
275: 		hi = min(hi, l.unstable.offset-1)
276: 	}
277: 	return hi
278: }
