327: func (l *raftLog) commitTo(tocommit uint64) {
328: 	// never decrease commit
329: 	if l.committed < tocommit {
330: 		if l.lastIndex() < tocommit {
331: 			l.logger.Panicf("tocommit(%d) is out of range [lastIndex(%d)]. Was the raft log corrupted, truncated, or lost?", tocommit, l.lastIndex())
332: 		}
333: 		l.committed = tocommit
334: 	}
335: }
