337: func (l *raftLog) appliedTo(i uint64, size entryEncodingSize) {
338: 	if l.committed < i || i < l.applied {
339: 		l.logger.Panicf("applied(%d) is out of range [prevApplied(%d), committed(%d)]", i, l.applied, l.committed)
340: 	}
341: 	l.applied = i
342: 	l.applying = max(l.applying, i)
343: 	if l.applyingEntsSize > size {
344: 		l.applyingEntsSize -= size
345: 	} else {
346: 		// Defense against underflow.
347: 		l.applyingEntsSize = 0
348: 	}
349: 	l.applyingEntsPaused = l.applyingEntsSize >= l.maxApplyingEntsSize
350: }
