352: func (l *raftLog) acceptApplying(i uint64, size entryEncodingSize, allowUnstable bool) {
353: 	if l.committed < i {
354: 		l.logger.Panicf("applying(%d) is out of range [prevApplying(%d), committed(%d)]", i, l.applying, l.committed)
355: 	}
356: 	l.applying = i
357: 	l.applyingEntsSize += size
358: 	// Determine whether to pause entry application until some progress is
359: 	// acknowledged. We pause in two cases:
360: 	// 1. the outstanding entry size equals or exceeds the maximum size.
361: 	// 2. the outstanding entry size does not equal or exceed the maximum size,
362: 	//    but we determine that the next entry in the log will push us over the
363: 	//    limit. We determine this by comparing the last entry returned from
364: 	//    raftLog.nextCommittedEnts to the maximum entry that the method was
365: 	//    allowed to return had there been no size limit. If these indexes are
366: 	//    not equal, then the returned entries slice must have been truncated to
367: 	//    adhere to the memory limit.
368: 	l.applyingEntsPaused = l.applyingEntsSize >= l.maxApplyingEntsSize ||
369: 		i < l.maxAppliableIndex(allowUnstable)
370: }
