440: // isUpToDate determines if a log with the given last entry is more up-to-date
441: // by comparing the index and term of the last entries in the existing logs.
442: //
443: // If the logs have last entries with different terms, then the log with the
444: // later term is more up-to-date. If the logs end with the same term, then
445: // whichever log has the larger lastIndex is more up-to-date. If the logs are
446: // the same, the given log is up-to-date.
447: func (l *raftLog) isUpToDate(their entryID) bool {
448: 	our := l.lastEntryID()
449: 	return their.term > our.term || their.term == our.term && their.index >= our.index
450: }
