460: func (l *raftLog) maybeCommit(at entryID) bool {
461: 	// NB: term should never be 0 on a commit because the leader campaigned at
462: 	// least at term 1. But if it is 0 for some reason, we don't consider this a
463: 	// term match.
464: 	if at.term != 0 && at.index > l.committed && l.matchTerm(at) {
465: 		l.commitTo(at.index)
466: 		return true
467: 	}
468: 	return false
